const body = $json.body || $json;
const payload = body.payload || body;
const booking = payload.booking || payload;
const isBokunBooking = Boolean(booking.bookingReference || booking.confirmationCode || booking.bookingId);
const status = booking.status || payload.status || (isBokunBooking ? 'bokun_booking' : 'lead');
const tour = booking.tourName || booking.tour || booking.tourId || payload.tourName || payload.tourId || 'Tour';
const customer = booking.customerName || booking.name || payload.name || 'customer';
const date = booking.desiredDate || booking.date || payload.desiredDate || '';
const time = booking.preferredTime || booking.time || payload.preferredTime || '';
const guests = booking.guests || payload.guests || '';
const phone = booking.phone || payload.phone || '';
const checkoutUrl = booking.bookingCheckoutUrl || payload.bookingCheckoutUrl || '';
const text = isBokunBooking
  ? `Bókun booking received: ${tour} ${date} ${time} for ${guests}. Customer: ${customer}. Reference: ${booking.bookingReference || booking.confirmationCode || booking.bookingId}.`
  : `Lead received. Send checkout link or create/hold in Bókun before confirming: ${tour} ${date} ${time} for ${guests}. Customer: ${customer}. Phone: ${phone}.${checkoutUrl ? ` Checkout: ${checkoutUrl}` : ''}`;
return [{ json: { isBokunBooking, status, tour, customer, date, time, guests, phone, checkoutUrl, text, payload } }];
